#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    auto apply_op = [&](int x, int y){
        vector<int> np;
        for(int i = n-y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n-y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
    };

    vector<pair<int,int>> ops;

    for(int t = 0; t < n-2; t++){
        int pos = -1;
        for(int i = 0; i < n; i++) if(p[i] == t+1){ pos = i; break; }
        if(pos == t) continue;

        // Move element at pos to position n-1
        if(pos != n-1){
            // Use x = pos+1, y = 1: element at pos (in prefix) goes to n - (pos+1) + pos = n-1
            // Need pos+1+1 < n => pos < n-2
            int x = pos+1, y = 1;
            if(x + y < n && x >= 1 && y >= 1){
                ops.push_back({x, y});
                apply_op(x, y);
            }
        }
        // Now element should be at n-1, move to t
        // y = t+1, x = 1, need 1+t+1 < n => t < n-2 (always true in loop)
        if(p[n-1] == t+1 && t+2 < n){
            int x = 1, y = t+1;
            ops.push_back({x, y});
            apply_op(x, y);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n", x, y);
}
